class Solution:
    def countIslands(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        idx = lambda i, j: i * n + j
        parent = list(range(m * n))
        size = [1] * (m * n)
        ssum = [grid[i][j] for i in range(m) for j in range(n)]

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            ssum[ra] += ssum[rb]

        for i in range(m):
            for j in range(n):
                if grid[i][j] > 0:
                    if i + 1 < m and grid[i+1][j] > 0:
                        union(idx(i, j), idx(i+1, j))
                    if j + 1 < n and grid[i][j+1] > 0:
                        union(idx(i, j), idx(i, j+1))

        return sum(1 for i in range(m * n)
                   if find(i) == i and ssum[i] > 0 and ssum[i] % k == 0)

