class Solution {
    vector<int> parent, sz;
    vector<long long> ssum;
    int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        parent[rb] = ra;
        sz[ra] += sz[rb];
        ssum[ra] += ssum[rb];
    }
public:
    int countIslands(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        parent.resize(m * n); sz.assign(m * n, 1); ssum.resize(m * n);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                ssum[i * n + j] = grid[i][j];
        auto idx = [&](int i, int j) { return i * n + j; };
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    if (i + 1 < m && grid[i+1][j] > 0) unite(idx(i,j), idx(i+1,j));
                    if (j + 1 < n && grid[i][j+1] > 0) unite(idx(i,j), idx(i,j+1));
                }
            }
        int ans = 0;
        for (int i = 0; i < m * n; i++)
            if (find(i) == i && ssum[i] > 0 && ssum[i] % k == 0) ans++;
        return ans;
    }
};

