class Solution {
    private int[] parent, sz;
    private long[] ssum;

    private int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }

    private void unite(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        sz[ra] += sz[rb];
        ssum[ra] += ssum[rb];
    }

    public int countIslands(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        parent = new int[m * n];
        sz = new int[m * n];
        ssum = new long[m * n];
        for (int i = 0; i < m * n; i++) { parent[i] = i; sz[i] = 1; }
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                ssum[i * n + j] = grid[i][j];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    if (i + 1 < m && grid[i+1][j] > 0) unite(i * n + j, (i+1) * n + j);
                    if (j + 1 < n && grid[i][j+1] > 0) unite(i * n + j, i * n + j + 1);
                }
            }
        int ans = 0;
        for (int i = 0; i < m * n; i++)
            if (find(i) == i && ssum[i] > 0 && ssum[i] % k == 0) ans++;
        return ans;
    }
}

