var countIslands = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const parent = Array.from({length: m * n}, (_, i) => i);
    const sz = new Array(m * n).fill(1);
    const ssum = [];
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) ssum.push(grid[i][j]);
    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function unite(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (sz[ra] < sz[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        sz[ra] += sz[rb];
        ssum[ra] += ssum[rb];
    }
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) {
            if (grid[i][j] > 0) {
                if (i + 1 < m && grid[i+1][j] > 0) unite(i * n + j, (i+1) * n + j);
                if (j + 1 < n && grid[i][j+1] > 0) unite(i * n + j, i * n + j + 1);
            }
        }
    let ans = 0;
    for (let i = 0; i < m * n; i++)
        if (find(i) === i && ssum[i] > 0 && ssum[i] % k === 0) ans++;
    return ans;
};
